Navigator.of(context).pushAndRemoveUntil(
  MaterialPageRoute(builder: (_) => const HomePage()),
  (route) => false, // removes everything
);

final picked = await Navigator.of(context).push<Color>(
  MaterialPageRoute(builder: (_) => const ColorPicker()),
);
if (picked != null && context.mounted) {
  setState(() => color = picked);
}

// in ColorPicker
Navigator.pop(context, Colors.teal);

final router = GoRouter(
  redirect: (context, state) =>
      !auth.isLoggedIn && state.matchedLocation != '/login' ? '/login' : null,
  routes: [
    GoRoute(path: '/', builder: (_, __) => const HomePage()),
    GoRoute(
      path: '/users/:id',
      builder: (_, s) => UserPage(id: s.pathParameters['id']!),
    ),
  ],
);

